/bin/bash -lc "node --input-type=module <<'EOF'
import { DatabaseSync } from 'node:sqlite';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import { rmSync } from 'node:fs';
const path = '/tmp/job-tracker-worker-check.db';
try { rmSync(path); rmSync(path + '-wal'); rmSync(path + '-shm'); } catch {}
const db = new DatabaseSync(path);
db.exec('PRAGMA journal_mode=WAL; CREATE TABLE jobs (id TEXT PRIMARY KEY,status TEXT,input TEXT,steps INTEGER,fail_attempts INTEGER,attempts INTEGER DEFAULT 0,progress_completed INTEGER DEFAULT 0,result_output TEXT,error TEXT,created_at TEXT,updated_at TEXT,available_at INTEGER DEFAULT 0,idempotency_key TEXT UNIQUE,payload TEXT); CREATE TABLE worker_heartbeat(id INTEGER PRIMARY KEY,seen_at INTEGER);');
const now = new Date().toISOString();
const add = db.prepare(\"INSERT INTO jobs(id,status,input,steps,fail_attempts,created_at,updated_at,payload) VALUES(?, 'queued', ?, 1, ?, ?, ?, '{}')\");
add.run('retry', 'hello', 2, now, now); add.run('fail', 'bye', 4, now, now);
const child = spawn(process.execPath, ['--disable-warning=ExperimentalWarning','dist/worker.js'], { env: { ...process.env, DATABASE_PATH: path }, stdio: 'ignore' });
const deadline = Date.now() + 8000;
let jobs;
while (Date.now() < deadline) { jobs = db.prepare('SELECT id,status,attempts,result_output,error FROM jobs ORDER BY id').all(); if (jobs.every(j => j.status === 'completed' || j.status === 'failed')) break; await sleep(100); }
child.kill('SIGTERM'); await new Promise(resolve => child.once('exit', resolve));
console.log(JSON.stringify(jobs));
db.close();
if ("'!jobs || jobs[0].status !== '"'failed' || jobs[0].attempts "'!== 3 || jobs[1].status !== '"'completed' || jobs[1].attempts "'!== 3 || jobs[1].result_output !== '"'HELLO') process.exitCode = 1;
EOF"

